import { inversifyContainer } from '../inversify/container';
import { IBaseSettingsResponse } from '../types';

const FREE_PLAY_VALUE: number = 10; // 10 is the value of a freeplay credit
export class Stake {
    public static get Instance(): Stake { return this._instance || (this._instance = new Stake()); }
    private static _instance: Stake;

    private _index: number = 0;
    private _stakes: number[] = [];
    private _initialStake: number = 5;

    private constructor() { }

    public set index(ind: number) {
        this._index = ind;
    }

    public get stakes(): number[] {
        return this._stakes;
    }

    public set stakes(stakesArray: number[]) {
        this._stakes = stakesArray;
    }

    public get initialStake(): number {
        if (inversifyContainer.cabinet.inFreePlay) {
            return FREE_PLAY_VALUE;
        }

        return this._initialStake;
    }

    public set initialStake(initialStake: number) {
        this._initialStake = initialStake;
    }

    public get currentStake(): number {
        if (inversifyContainer.cabinet.inFreePlay) {
            return FREE_PLAY_VALUE;
        }

        return this._stakes[this._index];
    }

    public get formattedStake(): string {
        return inversifyContainer.currencyFormatter.precise(this.currentStake);
    }

    public get lowestStake(): number {
        return this._stakes[0];
    }

    public get highestStake(): number {
        return this._stakes[this._stakes.length - 1];
    }

    public canIncreaseStake(): boolean {
        return this._index + 1 < this._stakes.length;
    }

    public canDecreaseStake(): boolean {
        return this._index - 1 >= 0;
    }

    public increaseStake(): void {
        if (this.canIncreaseStake()) {
            this._index++;
        }
    }

    public decreaseStake(): void {
        if (this.canDecreaseStake()) {
            this._index--;
        }
    }

    public updateStakes(gameSettings: IBaseSettingsResponse, currentStake: number = this._stakes[this._index]): void {
        // If the last used stake is not found in the new stake array use the default
        currentStake = gameSettings.StakeOptions.indexOf(currentStake) < 0 ? gameSettings.DefaultStake : currentStake;

        this._stakes = gameSettings.StakeOptions;
        this._index = this._stakes.indexOf(currentStake);
    }
}

export const stake = Stake.Instance;
